mapper.select:
SELECT s.*
FROM task_submission s
INNER JOIN learning_task t ON t.task_no = s.task_no
WHERE s.student_no = #{studentNo}
  AND t.course_code = #{courseCode}
ORDER BY s.submit_time DESC, s.submission_id DESC

mapper.update:
UPDATE task_submission
SET status = 'superseded'
WHERE task_no = #{taskNo}
  AND student_no = #{studentNo}
  AND (status IS NULL OR status != 'superseded')
